css:
.stormsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e8eef6;
    background: linear-gradient(160deg, #0a1422 0%, #101d31 55%, #15263f 100%);
    border-radius: 18px;
}

.stormsim-container * {
    box-sizing: border-box;
}

.stormsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #15263f 0%, #1c3354 55%, #b9551b 130%);
    color: #f3f7fc;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.45);
    border: 1px solid #27405f;
}

.stormsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    text-shadow: 0 2px 12px rgba(0, 0, 0, 0.4);
}

.stormsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffd7a8;
    background: rgba(255, 138, 41, 0.16);
    border: 1px solid rgba(255, 138, 41, 0.35);
    padding: 5px 14px;
    border-radius: 999px;
}

.stormsim-subtitle {
    margin: 12px auto 0;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d3deee;
}

.stormsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #aebfd6;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.stormsim-period-counter #currentDay,
.stormsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #ffffff;
}

.stormsim-round-name {
    background: rgba(94, 142, 214, 0.22);
    color: #cfe0ff;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid rgba(94, 142, 214, 0.4);
}

.stormsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffce9a;
    background: rgba(255, 138, 41, 0.14);
    padding: 4px 12px;
    border-radius: 999px;
    border: 1px solid rgba(255, 138, 41, 0.3);
}

.stormsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.stormsim-status-card {
    background: linear-gradient(160deg, #16263d 0%, #122036 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #27405f;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.3);
    border-top: 4px solid #5e8ed6;
}

.stormsim-card-flow { border-top-color: #2fae7a; }
.stormsim-card-trust { border-top-color: #f2a93b; }
.stormsim-card-coord { border-top-color: #5e8ed6; }
.stormsim-card-reserve { border-top-color: #9b7fd6; }

.stormsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8aa0bf;
}

.stormsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #ffffff;
}

.stormsim-card-flow .stormsim-value { color: #45d39a; }
.stormsim-card-trust .stormsim-value { color: #f8bd5f; }
.stormsim-card-coord .stormsim-value { color: #82aef0; }
.stormsim-card-reserve .stormsim-value { color: #bba6ee; }

.stormsim-sublabel {
    font-size: 0.76rem;
    color: #7e93b3;
    line-height: 1.35;
}

.stormsim-flow-fail .stormsim-value { color: #f0644f; }
.stormsim-flow-target .stormsim-value { color: #45d39a; }

.stormsim-budget-bar {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
    gap: 8px 18px;
    background: #0c1726;
    color: #e8eef6;
    padding: 12px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.9rem;
    border: 1px solid #243a58;
}

.stormsim-budget-label,
.stormsim-staff-label {
    color: #8aa0bf;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    font-size: 0.74rem;
}

.stormsim-budget-bar #budgetDisplay {
    font-size: 1.02rem;
    letter-spacing: 0.3px;
    color: #ffce9a;
    margin-right: auto;
}

.stormsim-budget-bar #staffDisplay {
    font-size: 1.02rem;
    color: #82aef0;
}

.stormsim-budget-over #budgetDisplay,
.stormsim-budget-over #staffDisplay {
    color: #f0644f;
}

.stormsim-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(160deg, #16263d 0%, #122036 100%);
    border-left: 5px solid #f2a93b;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.28);
    border-top: 1px solid #27405f;
    border-right: 1px solid #27405f;
    border-bottom: 1px solid #27405f;
}

.stormsim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.stormsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #ffffff;
    margin-bottom: 6px;
}

.stormsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #c8d6ea;
}

.stormsim-briefing-text strong { color: #45d39a; }
.stormsim-briefing-text em { color: #ffce9a; font-style: italic; }

.stormsim-controls {
    background: linear-gradient(160deg, #16263d 0%, #11203699 100%);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #27405f;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.3);
}

.stormsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #ffffff;
    border-bottom: 2px solid #27405f;
    padding-bottom: 8px;
}

.stormsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #cfdcef;
    margin: 14px 0 6px;
}

.stormsim-container select,
.stormsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2f4a6c;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0e1c30;
    color: #e8eef6;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.stormsim-container select:focus,
.stormsim-container input[type="number"]:focus {
    outline: none;
    border-color: #f2a93b;
    box-shadow: 0 0 0 3px rgba(242, 169, 59, 0.18);
}

.stormsim-container select option {
    background-color: #0e1c30;
    color: #e8eef6;
}

.stormsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #f2a93b;
}

.stormsim-range-readout,
.stormsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #aebfd6;
    margin-top: 4px;
}

.stormsim-range-readout span:last-child,
.stormsim-alloc-readout span:nth-child(2) {
    color: #45d39a;
    font-weight: 800;
}

.stormsim-hint {
    font-size: 0.8rem;
    color: #7e93b3;
    margin-top: 4px;
    line-height: 1.4;
}

.stormsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.stormsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #0f1e33;
    border: 1px solid #2a4264;
    border-radius: 9px;
    padding: 8px 12px;
}

.stormsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #cfdcef;
}

.stormsim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.stormsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.stormsim-container .btn-primary {
    background: linear-gradient(135deg, #d96f1e 0%, #f2a93b 100%);
    border: none;
    color: #1a0f04;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 18px rgba(217, 111, 30, 0.34);
}

.stormsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.stormsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #2f4a6c;
    color: #aebfd6;
}

.stormsim-coach {
    background: linear-gradient(135deg, #1c3354 0%, #122036 100%);
    color: #e8eef6;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.35);
    border: 1px solid #2f4a6c;
    border-left: 5px solid #f2a93b;
}

.stormsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffce9a;
    margin-bottom: 8px;
}

.stormsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #d3deee;
}

.stormsim-coach-body strong { color: #45d39a; }
.stormsim-coach-body em { color: #ffce9a; font-style: italic; }

.stormsim-history,
.stormsim-chart {
    background: linear-gradient(160deg, #16263d 0%, #122036 100%);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #27405f;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.3);
}

.stormsim-history h3,
.stormsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #ffffff;
}

.stormsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #cfdcef;
}

.stormsim-container table#usfHistoryTable th {
    background: #0f1e33;
    color: #9fb6d6;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #2a4264;
}

.stormsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #1e3149;
}

.stormsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #11203699;
}

.stormsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .stormsim-container {
        padding: 14px;
    }
    .stormsim-header h1 {
        font-size: 1.7rem;
    }
    .stormsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .stormsim-value {
        font-size: 2rem;
    }
    .stormsim-clock {
        margin-left: 0;
    }
    .stormsim-period-counter {
        font-size: 0.88rem;
    }
    .stormsim-budget-bar {
        flex-direction: column;
        align-items: flex-start;
        gap: 4px;
    }
    .stormsim-budget-bar #budgetDisplay {
        margin-right: 0;
    }
    .stormsim-alloc-row {
        flex-wrap: wrap;
    }
    .stormsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .stormsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ── v1.1.0 completion scorecard (append-only, namespaced .sm-cm-*, dark) ── */
.sm-cm { margin-top: 8px; }
.sm-cm-incomplete { text-align: center; color: #9db0c9; font-size: 1rem; padding: 18px; }
.sm-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.sm-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #15263f 0%, #1c3354 55%, #b9551b 130%); color: #f4f8ff; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(0, 0, 0, 0.38); }
.sm-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.sm-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.82; }
.sm-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #f2c79b; }
.sm-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #16263d; border: 1px solid #274063; border-left: 5px solid #b9551b; border-radius: 14px; padding: 16px 20px; }
.sm-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #9db0c9; }
.sm-cm-verdict-tier { margin-top: 4px; font-size: 1.5rem; font-weight: 800; color: #f4f8ff; line-height: 1.15; }
.sm-cm-section { margin-bottom: 16px; }
.sm-cm-section-h { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #86a0c2; margin-bottom: 8px; }
.sm-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.sm-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.sm-cm-ok { background: rgba(47, 174, 122, 0.18); color: #6fe0ac; border-color: rgba(47, 174, 122, 0.45); }
.sm-cm-no { background: rgba(214, 78, 54, 0.18); color: #f6a08d; border-color: rgba(214, 78, 54, 0.45); }
.sm-cm-ico { font-weight: 800; }
.sm-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; }
.sm-cm-kpi { background: #16263d; border: 1px solid #274063; border-top: 4px solid #2fae7a; border-radius: 12px; padding: 14px 12px; text-align: center; }
.sm-cm-kpi-val { font-size: 1.6rem; font-weight: 800; color: #f4f8ff; line-height: 1; }
.sm-cm-kpi-lbl { margin-top: 6px; font-size: 0.82rem; font-weight: 700; color: #b7c6dc; }
.sm-cm-kpi-sub { margin-top: 2px; font-size: 0.7rem; color: #7f96b4; }
.sm-cm-insights { margin: 0; padding-left: 18px; color: #dbe6f4; }
.sm-cm-insights li { margin: 4px 0; font-size: 0.92rem; line-height: 1.45; }
@media (max-width: 560px) { .sm-cm-head { flex-direction: column; } .sm-cm-score { min-width: 0; } }

