(function() {
    'use strict';

    class StormAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Lead Through the Storm`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Severnvale NHS Trust).
            this.START_FLOW = 30;        // surge unstabilised at the outset
            this.START_TRUST = 25;       // frightened, exhausted Friday-night frontline
            this.START_COORD = 20;       // hierarchical culture, blind centre, two sites
            this.TARGET_FLOW = 70;       // hour-48 review threshold
            this.CONTINGENCY_CAP = 1200; // GBP 1.2M, in thousands
            this.STAFF_CAP = 40;         // 40 redeployable staff
            this.STAFF_RESERVE_MIN = 6;  // a deliberate reserve worth protecting

            // Concept truths.
            this.TRUE_PICTURE = `ground`;
            this.TRUE_RISK = `exit`;
            this.TRUE_RULE = `clinical`;
            this.TRUE_MODEL = `distributed`;
            this.TRUE_COORD = `liaison`;
            this.TRUE_MESSAGE = `empower`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    flow: this.START_FLOW,
                    trust: this.START_TRUST,
                    coord: this.START_COORD,
                    contingencyUsed: 0,
                    staffUsed: 0,
                    reserveHeld: this.STAFF_CAP,
                    bottleneck: false,
                    targetMissed: false,
                    flowHistory: [this.START_FLOW],
                    trustHistory: [this.START_TRUST],
                    coordHistory: [this.START_COORD],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / neutral mix — NOT the textbook play.
                state.decisions = {
                    picture: `single`,
                    risk: `staff`,
                    push: 45,
                    rule: `firstcome`,
                    trauma: 10,
                    decon: 8,
                    urgent: 8,
                    contingency: 400,
                    model: `calibrated`,
                    coord: `micromanage`,
                    intent: 50,
                    message: `await`,
                    optimise: `balance`,
                    brief: `numbers`,
                    confidence: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const pic = document.getElementById(`pictureInput`);
                const risk = document.getElementById(`riskInput`);
                const push = document.getElementById(`pushInput`);
                if (pic) decisions.picture = pic.value;
                if (risk) decisions.risk = risk.value;
                if (push) decisions.push = parseInt(push.value, 10);
                if (!Number.isFinite(decisions.push) || decisions.push < 0 || decisions.push > 100) {
                    warn(`warn_push_range`); return false;
                }
            } else if (round === 2) {
                const rule = document.getElementById(`ruleInput`);
                if (rule) decisions.rule = rule.value;
                const trauma = document.getElementById(`traumaInput`);
                const decon = document.getElementById(`deconInput`);
                const urgent = document.getElementById(`urgentInput`);
                const cont = document.getElementById(`contingencyInput`);
                if (trauma) decisions.trauma = parseInt(trauma.value, 10);
                if (decon) decisions.decon = parseInt(decon.value, 10);
                if (urgent) decisions.urgent = parseInt(urgent.value, 10);
                if (cont) decisions.contingency = parseFloat(cont.value);
                const parts = [decisions.trauma, decisions.decon, decisions.urgent];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_staff_negative`); return false;
                }
                const totalStaff = decisions.trauma + decisions.decon + decisions.urgent;
                if (totalStaff > this.STAFF_CAP) {
                    warn(`warn_staff_cap`); return false;
                }
                if (!Number.isFinite(decisions.contingency) || decisions.contingency < 0 || decisions.contingency > this.CONTINGENCY_CAP) {
                    warn(`warn_contingency_range`); return false;
                }
            } else if (round === 3) {
                const model = document.getElementById(`modelInput`);
                const coord = document.getElementById(`coordInput`);
                const intent = document.getElementById(`intentInput`);
                if (model) decisions.model = model.value;
                if (coord) decisions.coord = coord.value;
                if (intent) decisions.intent = parseInt(intent.value, 10);
                if (!Number.isFinite(decisions.intent) || decisions.intent < 0 || decisions.intent > 100) {
                    warn(`warn_intent_range`); return false;
                }
            } else if (round === 4) {
                const msg = document.getElementById(`messageInput`);
                const opt = document.getElementById(`optimiseInput`);
                const br = document.getElementById(`briefInput`);
                const conf = document.getElementById(`confidenceInput`);
                if (msg) decisions.message = msg.value;
                if (opt) decisions.optimise = opt.value;
                if (br) decisions.brief = br.value;
                if (conf) decisions.confidence = parseInt(conf.value, 10);
                if (!Number.isFinite(decisions.confidence) || decisions.confidence < 0 || decisions.confidence > 100) {
                    warn(`warn_confidence_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // flowDelta   = surge containment / patient flow this round
            // trustDelta  = whether the frontline feels safe to act
            // coordDelta  = command coherence across two blind sites
            let flowDelta = 0, trustDelta = 0, coordDelta = 0;
            let spend = 0, staffNow = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Round 1 — sensemaking under information loss (Weick).
                switch (d.picture) {
                    case `ground`: coordDelta += 14; flowDelta += 8; trustDelta += 6; coachKey = `coach_r1_ground`; break;
                    case `single`: coordDelta -= 4; flowDelta -= 2; coachKey = `coach_r1_single`; break;
                    case `wait`: flowDelta -= 12; coordDelta -= 8; trustDelta -= 6; coachKey = `coach_r1_wait`; break;
                    case `assume`: flowDelta -= 8; coordDelta -= 6; coachKey = `coach_r1_assume`; break;
                }

                // Naming the real next-six-hours risk: exit/flow block is the genuine surge killer.
                if (d.risk === this.TRUE_RISK) {
                    flowDelta += 10; coordDelta += 4;
                    if (d.picture === this.TRUE_PICTURE) coachKey = `coach_r1_sharp`;
                } else if (d.risk === `staff`) {
                    flowDelta += 2; trustDelta += 2;
                } else if (d.risk === `audit`) {
                    flowDelta -= 6; coachKey = `coach_r1_audit`;
                } else {
                    flowDelta -= 2;
                }

                // Pushing decisions to the edge: with a blind centre, delegation buys speed.
                if (d.push >= 60) { coordDelta += 8; flowDelta += 6; trustDelta += 6; }
                else if (d.push <= 25) { coordDelta -= 8; flowDelta -= 6; trustDelta -= 4; coachKey = `coach_r1_central`; }

                summaryKey = (d.picture === this.TRUE_PICTURE && d.risk === this.TRUE_RISK) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Round 2 — rule-based triage with a protected reserve (Common Error 3 & 5).
                staffNow = d.trauma + d.decon + d.urgent;
                spend = d.contingency;
                const reserve = this.STAFF_CAP - staffNow;

                switch (d.rule) {
                    case `clinical`: flowDelta += 14; coordDelta += 8; trustDelta += 4; coachKey = `coach_r2_clinical`; break;
                    case `firstcome`: flowDelta -= 6; coordDelta -= 4; coachKey = `coach_r2_firstcome`; break;
                    case `loudest`: flowDelta -= 8; coordDelta -= 8; trustDelta -= 4; coachKey = `coach_r2_loudest`; break;
                    case `equal`: flowDelta -= 4; coordDelta += 2; coachKey = `coach_r2_equal`; break;
                }

                // Allocation shape: trauma surge is the dominant demand; starving it hurts flow.
                if (d.trauma >= 14) { flowDelta += 8; }
                else if (d.trauma <= 4) { flowDelta -= 8; coachKey = `coach_r2_starvetrauma`; }
                if (d.decon >= 4) { flowDelta += 4; } else { flowDelta -= 4; }
                if (d.urgent >= 4) { trustDelta += 4; } else { trustDelta -= 4; coachKey = `coach_r2_droppedcare`; }

                // Pacing / reserve protection — front-loading everything leaves nothing for night two.
                if (reserve >= this.STAFF_RESERVE_MIN && d.contingency <= 700) {
                    flowDelta += 6; trustDelta += 6; coordDelta += 4;
                    if (d.rule === this.TRUE_RULE) coachKey = `coach_r2_paced`;
                } else if (reserve < this.STAFF_RESERVE_MIN && d.contingency >= 900) {
                    flowDelta -= 10; trustDelta -= 10; coachKey = `coach_r2_frontload`;
                } else if (d.contingency >= 900 || reserve < this.STAFF_RESERVE_MIN) {
                    flowDelta -= 4; trustDelta -= 4; coachKey = (coachKey === `coach_r2_clinical`) ? `coach_r2_thinreserve` : coachKey;
                }
                // Under-resourcing the response also fails the surge.
                if (staffNow <= 14 && d.contingency <= 200) { flowDelta -= 8; coachKey = `coach_r2_underspend`; }

                ds.reserveHeld = reserve;

                summaryKey = (d.rule === this.TRUE_RULE && reserve >= this.STAFF_RESERVE_MIN && d.contingency <= 700) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Round 3 — centralized vs distributed leadership (the Spyridonidis core).
                switch (d.model) {
                    case `distributed`: flowDelta += 12; coordDelta += 6; trustDelta += 10; coachKey = `coach_r3_distributed`; break;
                    case `calibrated`: flowDelta += 6; coordDelta += 8; trustDelta += 4; coachKey = `coach_r3_calibrated`; break;
                    case `central`: flowDelta -= 14; coordDelta -= 10; trustDelta -= 8; ds.bottleneck = true; coachKey = `coach_r3_central`; break;
                }

                // Coordination mechanism across two blind sites.
                switch (d.coord) {
                    case `liaison`: coordDelta += 12; flowDelta += 4; break;
                    case `compete`: coordDelta -= 12; flowDelta -= 6; coachKey = `coach_r3_compete`; break;
                    case `micromanage`: coordDelta -= 8; flowDelta -= 4; trustDelta -= 4; coachKey = `coach_r3_micro`; break;
                }

                // Commander's intent: distribution WITHOUT a clear intent fragments (Common Error 2).
                if (d.model !== `central` && d.intent >= 70) {
                    coordDelta += 10; flowDelta += 6; trustDelta += 4;
                    if (d.model === this.TRUE_MODEL && d.coord === this.TRUE_COORD) coachKey = `coach_r3_missioncommand`;
                } else if (d.model === `distributed` && d.intent <= 35) {
                    coordDelta -= 14; flowDelta -= 8; coachKey = `coach_r3_nointent`;
                } else if (d.intent <= 35) {
                    coordDelta -= 6;
                }

                summaryKey = (d.model === this.TRUE_MODEL && d.intent >= 70 && d.coord === this.TRUE_COORD) ? `sum_r3_good` : (d.model === `central` ? `sum_r3_bottleneck` : `sum_r3_weak`);
            } else if (round === 4) {
                // Round 4 — framing as a leadership act + the hour-48 review (Common Errors 4 & 6).
                switch (d.message) {
                    case `empower`: trustDelta += 16; flowDelta += 8; coordDelta += 4; coachKey = `coach_r4_empower`; break;
                    case `await`: trustDelta -= 8; flowDelta -= 6; coachKey = `coach_r4_await`; break;
                    case `judgement`: coordDelta -= 10; flowDelta -= 4; trustDelta += 2; coachKey = `coach_r4_judgement`; break;
                    case `none`: trustDelta -= 12; coordDelta -= 4; coachKey = `coach_r4_nomessage`; break;
                }

                // Optimise for the ground, not the audience (Common Error 6).
                switch (d.optimise) {
                    case `ground`: trustDelta += 10; flowDelta += 8; coachKey = (d.message === this.TRUE_MESSAGE) ? `coach_r4_ground` : coachKey; break;
                    case `balance`: flowDelta += 2; break;
                    case `review`: trustDelta -= 12; flowDelta -= 6; coachKey = `coach_r4_review`; break;
                }

                // The briefing content — coherence with live evidence vs numbers vs excuses.
                switch (d.brief) {
                    case `cohere`: coordDelta += 12; flowDelta += 4; break;
                    case `numbers`: coordDelta += 2; break;
                    case `blame`: coordDelta -= 8; flowDelta -= 4; coachKey = `coach_r4_blame`; break;
                }

                // Conviction nudges trust and coordination.
                flowDelta += Math.round((d.confidence - 60) / 12);
                trustDelta += Math.round((d.confidence - 60) / 12);

                summaryKey = (d.message === this.TRUE_MESSAGE && d.optimise === `ground` && d.brief === `cohere`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.contingencyUsed = Math.min(this.CONTINGENCY_CAP, Math.round(ds.contingencyUsed + spend));
            ds.staffUsed = Math.min(this.STAFF_CAP, ds.staffUsed + staffNow);

            // Dampen positive gains so the meters keep headroom into the final round — this stops
            // a strong play pegging at 100 early, which would mask the cost of any single
            // Common-Error lever in the late rounds. Penalties land at full weight.
            const GAIN = 0.7;
            const damp = (x) => x >= 0 ? x * GAIN : x;

            // Trust and coordination move on their (dampened) deltas.
            ds.trust = Math.max(0, Math.min(100, ds.trust + damp(trustDelta)));
            ds.coord = Math.max(0, Math.min(100, ds.coord + damp(coordDelta)));

            // Flow stability is dragged down when trust and coordination are weak — a blind,
            // distrusted, incoherent command cannot actually stabilise the surge, so a high
            // flowDelta only fully lands when the frontline is with you and the sites cohere.
            const enabling = (ds.trust + ds.coord) / 200; // 0..1
            const flowGain = flowDelta >= 0 ? damp(flowDelta) * (0.55 + 0.45 * enabling) : flowDelta;
            ds.flow = Math.max(0, Math.min(100, ds.flow + flowGain));

            ds.flowHistory.push(Math.round(ds.flow));
            ds.trustHistory.push(Math.round(ds.trust));
            ds.coordHistory.push(Math.round(ds.coord));

            if (round === this.ROUNDS.length && ds.flow < this.TARGET_FLOW) ds.targetMissed = true;

            // v1.1.0 fix — persist composite where Express grading/reporting reads it
            // (results_utils.php express_resolveDomainScore -> performance.overallScore, then top-level score).
            const composite = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = composite;
            ds.score = composite;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                flow: Math.round(ds.flow),
                flowDelta: Math.round(flowGain),
                trust: Math.round(ds.trust),
                trustDelta: Math.round(trustDelta),
                coord: Math.round(ds.coord),
                coordDelta: Math.round(coordDelta),
                contingencyUsed: ds.contingencyUsed,
                staffUsed: ds.staffUsed,
                reserveHeld: ds.reserveHeld,
                bottleneck: ds.bottleneck,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: composite,
                overallScore: composite
            };
        }

