            if (push && pushReadout) {
                pushReadout.textContent = push.value;
                push.addEventListener(`input`, function() { pushReadout.textContent = push.value; });
            }

            // Intent slider readout.
            const intent = document.getElementById(`intentInput`);
            const intentReadout = document.getElementById(`intentReadout`);
            if (intent && intentReadout) {
                intentReadout.textContent = intent.value;
                intent.addEventListener(`input`, function() { intentReadout.textContent = intent.value; });
            }

            // Live staff-deployment total (against the 40 cap; the rest is the reserve).
            const staffIds = [`traumaInput`, `deconInput`, `urgentInput`];
            const staffReadout = document.getElementById(`staffReadout`);
            const recompute = function() {
                let total = 0;
                staffIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseInt(el.value, 10) || 0);
                });
                if (staffReadout) staffReadout.textContent = total;
                const bar = document.querySelector(`.stormsim-alloc-readout`);
                if (bar) bar.style.color = (total > self.STAFF_CAP) ? `#f0644f` : ``;
            };
            staffIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

