        _composite(ds) {
            // Verbatim v1.0.0 composite (was inline in getPerformanceSummary), extracted so the
            // per-period persisted score and the completion summary are identical by construction.
            const flow = Math.round(ds.flow);
            const trust = Math.round(ds.trust);
            const coord = Math.round(ds.coord);
            return Math.round(flow * 0.4 + trust * 0.3 + coord * 0.3);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const flow = Math.round(ds.flow);
            const trust = Math.round(ds.trust);
            const coord = Math.round(ds.coord);

            const stabilised = flow >= this.TARGET_FLOW;
            const coherent = trust >= 60 && coord >= 60;
            const composite = this._composite(ds);

            let tierKey = `grade_stripped`;
            if (stabilised && coherent && composite >= 72) tierKey = `grade_weathered`;
            else if (stabilised && coherent) tierKey = `grade_coherent`;
            else if (stabilised && ds.bottleneck) tierKey = `grade_paper`;
            else if (stabilised) tierKey = `grade_frayed`;
            else if (flow > this.START_FLOW + 18) tierKey = `grade_improving`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (stabilised && coherent) insights.push(window.mySimulation.t(`insight_weathered`));
            else if (stabilised && ds.bottleneck) insights.push(window.mySimulation.t(`insight_paper`));
            else if (stabilised) insights.push(window.mySimulation.t(`insight_frayed`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (coord < 50) insights.push(window.mySimulation.t(`insight_lowcoord`));
            if (trust < 50) insights.push(window.mySimulation.t(`insight_lowtrust`));
            if (ds.bottleneck) insights.push(window.mySimulation.t(`insight_bottleneck`));
            if (ds.contingencyUsed >= this.CONTINGENCY_CAP) insights.push(window.mySimulation.t(`insight_burned`));
            if (stabilised && coherent && composite >= 80) insights.push(window.mySimulation.t(`insight_exemplary`));

            return {
                flow: flow,
                trust: trust,
                coord: coord,
                stabilised: stabilised,
                coherent: coherent,
                bottleneck: ds.bottleneck,
                contingencyOk: ds.contingencyUsed <= this.CONTINGENCY_CAP,
                contingencyUsed: ds.contingencyUsed,
                composite: composite,
                performance: performance,
                performanceKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="sm-cm"><p class="sm-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="sm-cm-chip ` + (ok ? `sm-cm-ok` : `sm-cm-no`) + `">` +
                `<span class="sm-cm-ico">` + (ok ? `✓` : `✕`) + `</span>` + label + ` · ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="sm-cm-kpi"><div class="sm-cm-kpi-val">` + val +
                `</div><div class="sm-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="sm-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="sm-cm">` +
  `<div class="sm-cm-head">` +
    `<div class="sm-cm-score"><div class="sm-cm-score-num">` + Math.round(s.composite) +
       `<span class="sm-cm-score-den">/100</span></div>` +
       `<div class="sm-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="sm-cm-verdict"><div class="sm-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="sm-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="sm-cm-section"><div class="sm-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="sm-cm-chips">` + chip(!!s.stabilised, t(`cm_t_flow`)) + chip(!!s.coherent, t(`cm_t_coherent`)) +
      chip(!s.bottleneck, t(`cm_t_bottleneck`)) + chip(!!s.contingencyOk, t(`cm_t_contingency`)) + `</div></div>` +
  `<div class="sm-cm-section"><div class="sm-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="sm-cm-kpis">` +
      kpi(t(`cm_k_flow`), Math.round(s.flow) + `%`, t(`cm_sub_flow`)) +
      kpi(t(`cm_k_trust`), Math.round(s.trust), t(`cm_sub_trust`)) +
      kpi(t(`cm_k_coord`), Math.round(s.coord), t(`cm_sub_coord`)) +
      kpi(t(`cm_k_contingency`), `£` + Math.round(Number(s.contingencyUsed || 0)) + `k`, t(`cm_sub_contingency`)) +
    `</div></div>` +
  (insights ? `<div class="sm-cm-section"><div class="sm-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="sm-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
