        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.bottleneck) return window.mySimulation.t(`hint_bottleneck`);
            if (ds.coord < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_coord`);
            if (ds.trust < 35) return window.mySimulation.t(`hint_trust`);
            if (state.currentPeriod >= 3 && ds.flow < 50) return window.mySimulation.t(`hint_behind`);
            if (ds.flow >= this.TARGET_FLOW && ds.trust >= 60 && ds.coord >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

